function transform(occurrence, editor, file) {
  setTimeout(() => {
    const cursor = editor.getCursor();

    // Find the line containing [Dev]:
    for (let line = cursor.line; line >= 0; line--) {
      const text = editor.getLine(line);
      const devIndex = text.indexOf("[Dev]: ");

      if (devIndex !== -1) {
        // Put cursor immediately after "[Dev]: "
        editor.setCursor({
          line: line,
          ch: devIndex + 7
        });

        break;
      }
    }
  }, 10);

  return '<div class="char-devnote">\n[Dev]: \n\n</div>';
}

function transform(occurrence, editor, file) {
  setTimeout(() => {
    const cursor = editor.getCursor();
    const line = editor.getLine(cursor.line);

    const openParen = line.lastIndexOf("()", cursor.ch);

    if (openParen !== -1) {
      editor.setCursor({
        line: cursor.line,
        ch: openParen + 1
      });
    }
  }, 10);

  return '<span class="narrator">()</span>';
}

function transform(occurrence, editor, file) {
  var uid = 'LINKPICK_' + Date.now().toString(36) + Math.floor(Math.random() * 1296).toString(36);
  var placeholder = '<a href="obsidian://open?vault=PENDING&file=' + uid + '">Picking…</a>';
  try {
    var orig = '';
    try { orig = occurrence.original || ((occurrence.match && occurrence.match[0]) || ''); } catch (e0) {}
    if (orig && orig.indexOf('!link') === -1) return placeholder;
  } catch (e00) {}
  setTimeout(function () {
    try {
      var g = (typeof window !== 'undefined' && window) || globalThis;
      var appRef = (g && g.app) || null;
      if (!appRef) return;
      var vaultName = 'Lore';
      try { vaultName = appRef.vault.getName(); } catch (e) {}
      var mdFiles = [];
      try { mdFiles = appRef.vault.getMarkdownFiles(); } catch (e2) {}
      if (!mdFiles || mdFiles.length === 0) return;
      var Obs = null;
      try { Obs = require('obsidian'); } catch (e3) {}
      if (!Obs) { try { Obs = g.require('obsidian'); } catch (e4) {} }
      if (!Obs) { Obs = g.obsidian || null; }
      var replaceUid = function (finalTag) {
        try {
          var val = editor.getValue();
          var idx = val.indexOf(uid);
          if (idx === -1) return false;
          var start = val.lastIndexOf('<a ', idx);
          var closeTag = '</a>';
          var endIdx = val.indexOf(closeTag, idx);
          if (start === -1 || endIdx === -1) return false;
          endIdx += closeTag.length;
          var from = editor.offsetToPos(start);
          var to = editor.offsetToPos(endIdx);
          editor.replaceRange(finalTag, from, to);
          try { editor.setCursor(editor.offsetToPos(start + finalTag.length)); } catch (e5) {}
          return true;
        } catch (e6) { return false; }
      };
      var buildTag = function (chosen) {
        var rel = chosen.path.replace(/\.md$/i, '');
        var encFile = encodeURIComponent(rel);
        var encVault = encodeURIComponent(vaultName);
        return '<a href="obsidian://open?vault=' + encVault + '&file=' + encFile + '">' + chosen.basename + '</a>';
      };
      if (!Obs || !Obs.FuzzySuggestModal) return;
      var picker = new Obs.FuzzySuggestModal(appRef);
      picker.getItems = function () { return mdFiles; };
      picker.getItemText = function (f) { return f.path; };
      picker.onChooseItem = function (f) { replaceUid(buildTag(f)); };
      picker.open();
    } catch (err) {}
  }, 10);
  return placeholder;
}
